from typing import Any, Callable

from graphql.type import (
    GraphQLArgument,
    GraphQLField,
    GraphQLInputType,
    GraphQLOutputType,
    GraphQLList,
    GraphQLNonNull,
    GraphQLResolveInfo,
)

from graphql.type.definition import GraphQLInputTypeDefinition


def plural_identifying_root_field(
    arg_name: str,
    input_type: GraphQLInputType,
    output_type: GraphQLOutputType,
    resolve_single_input: Callable[[GraphQLResolveInfo, str], Any],
    description: str = None,
) -> GraphQLField:
    if isinstance(input_type, GraphQLNonNull):
        input_type = input_type.of_type
    if isinstance(input_type, GraphQLInputTypeDefinition):
        check_input_type = getattr(input_type, "graphql_type", None)
    else:
        # this is a bit inefficient until equivalent check is added to graphql-py https://github.com/graphql-python/graphql-py/issues/67
        check_input_type: Any = GraphQLList(GraphQLInputType)
    input_args = {
        arg_name: GraphQLArgument(
            GraphQLNonNull(GraphQLList(GraphQLNonNull(input_type)))
        ),
    }

    def resolve(_obj, info, **args):
        inputs = args[arg_name]
        return [resolve_single_input(info, input_) for input_ in inputs]

    return GraphQLField(
        GraphQLList(output_type),
        description=description,
        args=input_args,
        resolve=resolve,
    )

