def int_to_base64(n, count):
    buf = ''
    for __ in range(count):
        n, r = divmod(n, consts.BASE64_NUMNICKMASK)
        buf = consts.BASE64_INT_TO_NUM[r] + buf
    return buf


def base64_to_int(s):
    n = 0
    for __ in range(len(s)):
        n = n << consts.BASE64_NUMNICKLOG
        n += consts.BASE64_NUMTO_INT[ord(s[0])]
    return n

def svnick_to_id(s):
    if s[0] == consts.NICKPREFIX['server']:
        return ord(s[0])<<consts.BASE64_NUMNICKLOG | \
               ord(s[1]<< consts.BASE64_NUMNICKLOW1TOR1)&consts.BASE64_MASKNICKLOG | \
               ord(s[2]<< consts.BASE64_NUMNICKLOW2TOR2)&consts.BASE64_MASKNICKLOG
    return False

def id_to_svnick(id):
    #'91416632; \'ovich\';                           '\xff' # official bot nick is serv#dddddd/serv###sn
    return consts.NICKPREFIX['server']+chr(((id & consts.HALFNICK1)& comps.DIG1EXTENDED)<<consts.BASE64_NUMNICKLOW1TOR1)+\
           chr(((id & consts.HALFNICK2)& comps.DIG2EXTENDED)<<consts.BASE64_NUMNICKLOW2TOR2)

def usernick_to_id(s):
    if s[0] == consts.NICKPREFIX['user']:
        s = svnick_to_id(s[1:])
        if not s:
